function makeStringSorted(s) {
  const MOD = 1000000007n;
  const n = s.length;
  const power = (base, exponent) => {
    let result = 1n;
    while (exponent > 0n) {
      if (exponent % 2n === 1n) {
        result = result * base % MOD;
      }
      base = base * base % MOD;
      exponent /= 2n;
    }
    return result;
  };

  const fact = [1n];
  const inverse = [0n];
  for (let k = 1; k <= n; k++) {
    fact.push(fact[k - 1] * BigInt(k) % MOD);
    inverse.push(power(BigInt(k), MOD - 2n));
  }

  const count = new Array(26).fill(0);
  let invDenominator = 1n;
  let answer = 0n;
  for (let i = n - 1; i >= 0; i--) {
    const letter = s.charCodeAt(i) - 97;
    count[letter]++;
    invDenominator = invDenominator * inverse[count[letter]] % MOD;
    let smaller = 0;
    for (let c = 0; c < letter; c++) {
      smaller += count[c];
    }
    const ways = fact[n - 1 - i] * BigInt(smaller) % MOD * invDenominator % MOD;
    answer = (answer + ways) % MOD;
  }
  return Number(answer);
}

