function makeStringSorted(s) {
  if (s.length > 9) {
    // Too many steps to simulate: count smaller arrangements exactly with BigInt multinomials, left to right.
    const factorial = m => { let f = 1n; for (let k = 2n; k <= BigInt(m); k++) f *= k; return f; };
    const left = {};
    for (const ch of s) left[ch] = (left[ch] || 0) + 1;
    const arrangements = total => Object.values(left).reduce((acc, v) => acc / factorial(v), factorial(total));
    let rank = 0n;
    for (let p = 0; p < s.length; p++) {
      for (const ch of Object.keys(left)) {
        if (ch < s[p] && left[ch] > 0) {
          left[ch]--;
          rank += arrangements(s.length - p - 1);
          left[ch]++;
        }
      }
      left[s[p]]--;
    }
    return Number(rank % 1000000007n);
  }
  // Apply the operation literally and count; fine for short strings.
  const chars = s.split('');
  let operations = 0;
  for (;;) {
    let i = chars.length - 1;
    while (i >= 1 && !(chars[i] < chars[i - 1])) i--;
    if (i < 1) break;
    let j = i;
    while (j + 1 < chars.length && chars[j + 1] < chars[i - 1]) j++;
    const held = chars[i - 1];
    chars[i - 1] = chars[j];
    chars[j] = held;
    const tail = chars.splice(i).reverse();
    for (const ch of tail) chars.push(ch);
