function generate(rand, size) {
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const n = size === 'large' ? 2000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 8);
  const kinds = 1 + Math.floor(rand() * (size === 'large' ? 26 : 5));
  const first = Math.floor(rand() * (27 - kinds));
  let s = '';
  for (let k = 0; k < n; k++) s += alphabet[first + Math.floor(rand() * kinds)];
  return [s];
}
